package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MaxDiskMbVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property max disk mb of observability config ")
  void test_max_disk_mb_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> MaxDiskMbVO.tryFrom(null));
    Assertions.assertEquals(1, MaxDiskMbVO.from(1).getMaxDiskMb());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MaxDiskMbVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", MaxDiskMbVO.from(1).toString());
  }
}
